{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Absolute oral bioavailability of levodopa from standard Sinemet was 80.4% in healthy young volunteers after an overnight fast, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Absolute bioavailability of metoclopramide was 0.801 (80.1%) versus IV in six subjects after a 10 mg oral dose, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Absolute bioavailability of bumetanide was 81% versus intravenous dosing in healthy subjects after a 3 mg oral dose, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules show absolute or systemic oral bioavailability values above 20%, mostly 35-99%, with high assay-transfer scores; therefore high F is better supported.",
  "evidence_gaps": [
    "Molecule 10 includes one inconsistent record (C26) referring to phenytoin rather than phenylbutyrate; this card was discounted as a provenance conflict.",
    "Some records report extent of bioavailability or unspecified methods rather than absolute F, but absolute measurements are available for the key evidence molecules."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

